import json,sys
from pathlib import Path
import numpy as np
root=Path(sys.argv[1]);d=np.load(root/'standard_101/trajectory_9000.npz');data=json.dumps(dict(p=d['positions'].tolist(),g=d['goals'].tolist(),o=d['obstacles'][:3].tolist(),r=d['radii'][:3].tolist()))
html='''<!doctype html><meta charset="utf-8"><title>MASAC trajectory playback</title><style>body{font:16px system-ui;background:#101b2b;color:#eef;padding:24px}canvas{background:#18283d;width:900px;max-width:100%}input{width:300px}</style><h1>MASAC — recorded pilot trajectory</h1><p>Standard MASAC · training seed 101 · evaluation map 9000. Failure retained. Static spheres shown; moving obstacle omitted because its history was not recorded.</p><button id="play">Play / pause</button> Time <input id="time" type="range" min="0" value="0"> Rotate <input id="angle" type="range" min="0" max="628" value="60"><span id="label"></span><br><canvas id="c" width="1000" height="700"></canvas><script>const D=DATA,C=document.getElementById('c'),x=C.getContext('2d'),T=document.getElementById('time'),A=document.getElementById('angle');T.max=D.p.length-1;let running=false;function project(p){let a=A.value/100,u=p[0]-50,v=p[1]-50;return [500+5*(u*Math.cos(a)-v*Math.sin(a)),480+2.5*(u*Math.sin(a)+v*Math.cos(a))-5*p[2]]}function draw(){x.clearRect(0,0,1000,700);let t=+T.value;document.getElementById('label').textContent=(t*.2).toFixed(1)+' s';D.o.forEach((p,i)=>{let q=project(p);x.fillStyle='#60748788';x.beginPath();x.arc(...q,D.r[i]*5,0,Math.PI*2);x.fill()});['#4cc9f0','#f7a35c','#98e895'].forEach((col,i)=>{x.strokeStyle=col;x.fillStyle=col;x.beginPath();for(let k=0;k<=t;k++){let q=project(D.p[k][i]);if(k===0)x.moveTo(...q);else x.lineTo(...q)}x.stroke();let q=project(D.p[t][i]);x.beginPath();x.arc(...q,6,0,7);x.fill();q=project(D.g[i]);x.strokeRect(q[0]-6,q[1]-6,12,12)});}T.oninput=draw;A.oninput=draw;document.getElementById('play').onclick=()=>running=!running;setInterval(()=>{if(running){T.value=(+T.value+1)%D.p.length;draw()}},100);draw();</script>'''.replace('DATA',data)
(root/'playback.html').write_text(html)
